<script setup lang="ts">
import {ref} from 'vue';
type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
const props=defineProps<{request:Request;token:string;initialUsername:string}>();
const emit=defineEmits<{done:[]}>();const username=ref(props.initialUsername),password=ref(''),confirm=ref(''),busy=ref(false),error=ref(''),message=ref('');
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{if(props.token){if(password.value!==confirm.value)throw new Error('两次输入的密码不一致');const r=await props.request<{message:string}>('/auth/recovery/complete','POST',{token:props.token,password:password.value});password.value='';confirm.value='';message.value=r.message;}else{const r=await props.request<{message:string}>('/auth/recovery/request','POST',{username:username.value});message.value=r.message;}}catch(e){error.value=e instanceof Error?e.message:'操作未完成';}finally{busy.value=false;}}
</script>
<template><section class="recovery-card card"><span class="eyebrow">ACCOUNT RECOVERY</span><h2>{{token?'设置新的登录密码':'找回登录密码'}}</h2><p>{{token?'重置成功后，原账号的所有登录会话都会失效。':'使用已绑定核验邮箱的账号申请。未收到邮件时可联系管理员协助。'}}</p><form v-if="!message||!token" @submit.prevent="submit"><label v-if="!token">账号<input v-model="username" autocomplete="username" required maxlength="128" :disabled="busy"/></label><template v-else><label>新密码<input v-model="password" type="password" required minlength="12" maxlength="72" autocomplete="new-password" :disabled="busy"/></label><label>再次输入新密码<input v-model="confirm" type="password" required minlength="12" maxlength="72" autocomplete="new-password" :disabled="busy"/></label></template><div v-if="error" class="recovery-error" role="alert">{{error}}</div><button class="btn primary full" :disabled="busy">{{busy?'正在处理…':token?'确认重置':'申请找回链接'}}</button></form><p v-if="message" class="recovery-message" role="status">{{message}}</p><button class="text-button" :disabled="busy" @click="emit('done')">返回登录</button></section></template>
<style scoped>.recovery-card{max-width:520px;margin:35px auto;padding:35px}.recovery-card h2{font-size:25px;margin:15px 0}.recovery-card p{font-size:13px;line-height:1.9;color:#667a6c;margin:18px 0}.recovery-card label{display:flex;flex-direction:column;gap:9px;font-size:13px;color:#415b49;margin:20px 0}.recovery-card input{padding:12px;border:1px solid #cbd8ce;border-radius:7px;font-size:14px}.recovery-card>.text-button{margin-top:24px}.recovery-error{padding:14px;background:#fff0f1;color:#a32b36;border-radius:7px;margin-bottom:20px;font-size:13px;line-height:1.8}.recovery-card .recovery-message{padding:15px;background:#eaf4ec;color:#2f6844;border-radius:8px}@media(max-width:800px){.recovery-card{padding:25px}}</style>
